'use strict';

// ---------------------------------------------------------------------------
// PlantUML diagram rendering
// ---------------------------------------------------------------------------

const { pumlEscape } = require('../text-utils');
const { annotateExpr, exprTotalSuffix } = require('../constants');
const { THEMES } = require('../themes');
const { EDGE_LABELS_ENABLED, GLOBAL_BOXES_ENABLED, SCALE_MULTIPLIER } = require('../options');
const { launchStereotype, groupDir, classifyGrid, buildLabel, recordTypeSpan, edgeRecordCountBraces } = require('./node-label');
const { globalAlias, renderGlobalBox } = require('./global-boxes');

// Renders one node as a rectangle. Nodes whose grid can expand to more than
// one thread group (classifyGrid === 'multi') get a dashed border instead of
// the default solid one, via the <<multi>> stereotype.
function renderNodeBlock(n, indentLevel, table, theme, globalsIndex) {
    const stereo = launchStereotype(n);
    const grid = classifyGrid(n, table);
    const stereotypes = [`<<${stereo}>>`];
    if (n.isEntry) stereotypes.push('<<entry>>');
    if (grid.kind === 'multi') stereotypes.push('<<multi>>');

    const label = buildLabel(n, grid, table, theme, globalsIndex);
    const pad = '    '.repeat(indentLevel);
    return [`${pad}rectangle "${label}" as ${n.id} ${stereotypes.join(' ')}`];
}

function renderPlantUml(nodes, edges, externalIds, table, dark, globalsIndex) {
    const theme = dark ? THEMES.dark : THEMES.light;
    const lines = [];
    lines.push('@startuml WorkGraphDependencies');
    // PlantUML's own scale directive - raises the rendered .png's pixel
    // resolution proportionally (a raster format, rendered at a fixed base
    // DPI otherwise); .svg is vector, so this mainly affects its declared
    // width/height there. --scale on the CLI is this multiplier directly
    // (default 2). Deliberately NOT PlantUML's "scale N%" percentage
    // syntax - confirmed (via the local server in this environment) that
    // it's not supported by every server version and silently breaks
    // diagram-type autodetection, rendering an "Assumed diagram type:
    // sequence" error image instead, with no warning from fetchBinary()
    // since the response is still a 400 with a real (error) PNG body. The
    // plain multiplier form ("scale 2", "scale 1.5") is universally
    // supported - never switch this back to the percentage form.
    lines.push(`scale ${SCALE_MULTIPLIER}`);
    lines.push('hide empty description');
    if (theme.canvasBg) lines.push(`skinparam BackgroundColor ${theme.canvasBg}`);
    lines.push(`skinparam DefaultFontColor ${theme.fontColor}`);
    lines.push(`skinparam ArrowColor ${theme.arrowColor}`);
    lines.push(`skinparam ArrowFontColor ${theme.arrowFontColor}`);
    lines.push(`skinparam NoteBackgroundColor ${theme.noteBg}`);
    lines.push(`skinparam NoteBorderColor ${theme.noteBorder}`);
    lines.push('skinparam NoteBorderThickness 1');
    lines.push('skinparam NoteFontSize 9');
    lines.push(`skinparam NoteFontColor ${theme.fontColor}`);
    lines.push(`skinparam PackageBorderColor ${theme.packageBorder}`);
    if (theme.packageBg) lines.push(`skinparam PackageBackgroundColor ${theme.packageBg}`);
    lines.push(`skinparam PackageFontColor ${theme.fontColor}`);
    lines.push(`skinparam LegendBorderColor ${theme.legendBorder}`);
    if (theme.legendBg) lines.push(`skinparam LegendBackgroundColor ${theme.legendBg}`);
    lines.push(`skinparam LegendFontColor ${theme.fontColor}`);
    lines.push('skinparam rectangle {');
    lines.push('    RoundCorner 12');
    lines.push(`    BorderColor ${theme.rectBorder}`);
    lines.push(`    BackgroundColor<<broadcasting>> ${theme.broadcasting}`);
    lines.push(`    BackgroundColor<<coalescing>> ${theme.coalescing}`);
    lines.push(`    BackgroundColor<<thread>> ${theme.thread}`);
    lines.push(`    BackgroundColor<<mesh>> ${theme.mesh}`);
    lines.push(`    BackgroundColor<<unknown>> ${theme.unknown}`);
    lines.push(`    BackgroundColor<<external>> ${theme.external}`);
    lines.push(`    BorderColor<<entry>> ${theme.entryBorder}`);
    lines.push('    BorderThickness<<entry>> 3');
    lines.push('    BorderStyle<<external>> dashed');
    lines.push('    BorderStyle<<multi>> dashed');
    lines.push('}');
    if (GLOBAL_BOXES_ENABLED) {
        lines.push('skinparam database {');
        lines.push(`    BackgroundColor ${theme.globalBg}`);
        lines.push(`    BorderColor ${theme.globalBorder}`);
        lines.push('}');
    }
    lines.push('');

    // Group scanned nodes by their source subdirectory (nodes-compute / nodes-mesh).
    const byGroup = new Map();
    for (const n of nodes) {
        const g = groupDir(n);
        if (!byGroup.has(g)) byGroup.set(g, []);
        byGroup.get(g).push(n);
    }

    // Which node-groups actually reference each global. Always computed
    // (not just under --global-boxes): besides driving box replication
    // below, it's also what the legend's "Used?" column reads - gating this
    // on GLOBAL_BOXES_ENABLED left every global showing as unused there
    // whenever --global-boxes was off, which is wrong (the two are meant to
    // be independent - see --global-boxes/--global-list in the CLI help).
    const globalUsedByGroups = new Map();
    for (const n of nodes) {
        for (const name of n.globalsUsed || []) {
            const g = groupDir(n);
            if (!globalUsedByGroups.has(name)) globalUsedByGroups.set(name, new Set());
            globalUsedByGroups.get(name).add(g);
        }
    }

    // Global boxes are declared *before* that group's node rectangles (and
    // read via an edge running global -> node, see below) so PlantUML's
    // top-down layout naturally places them above the nodes that read them -
    // "may be interpreted as inputs" to the node, same as a producer node
    // feeding a consumer. Globals nobody reads anywhere no longer get a box
    // at all (the "globals (unused)" package was dropped) - every global,
    // used or not, is still listed in the dedicated legend table below.
    for (const [group, groupNodes] of [...byGroup.entries()].sort()) {
        lines.push(`package "${pumlEscape(group)}" {`);
        if (GLOBAL_BOXES_ENABLED) {
            const globalsInGroup = [...globalsIndex.values()]
                .filter((g) => globalUsedByGroups.get(g.name)?.has(group))
                .sort((a, b) => a.regType.localeCompare(b.regType) || a.regSlot - b.regSlot);
            for (const g of globalsInGroup) {
                lines.push(...renderGlobalBox(g, globalAlias(g.name, group), 1, theme));
            }
        }
        for (const n of groupNodes.sort((a, b) => a.id.localeCompare(b.id))) {
            lines.push(...renderNodeBlock(n, 1, table, theme, globalsIndex));
        }
        lines.push('}');
        lines.push('');
    }

    if (externalIds.size > 0) {
        lines.push('package "external / unresolved" {');
        for (const id of [...externalIds].sort()) {
            lines.push(`    rectangle "${pumlEscape(id)}\\n(not found in nodes-*)" as ${id} <<external>>`);
        }
        lines.push('}');
        lines.push('');
    }

    // Edge labels are drawn as a bordered "note on link" (rather than an
    // inline ": label") so each one gets a slight box around it. Suppressed
    // entirely (just the bare arrow) under --no-edge-label.
    for (const e of edges) {
        lines.push(`${e.from} --> ${e.to}`);
        if (!EDGE_LABELS_ENABLED) continue;

        const labelParts = [];
        if (e.recordType || (e.recordKind && e.recordKind.startsWith('Empty'))) {
            const countBraces = edgeRecordCountBraces(e.maxRecords, table);
            labelParts.push(`<i>${recordTypeSpan(e.recordType, theme)}</i>${countBraces}`);
        }
        if (e.varName) labelParts.push(`<size:8>${e.varName}</size>`);
        if (e.maxRecordsSharedWith) {
            labelParts.push(
                `<size:9>shared: ${annotateExpr(e.maxRecordsSharedWith, table)}${exprTotalSuffix(e.maxRecordsSharedWith, table)}</size>`
            );
        }

        if (labelParts.length) {
            lines.push('note on link');
            for (const p of labelParts) lines.push(`  ${pumlEscape(p)}`);
            lines.push('end note');
        }
    }

    // Otherwise the same arrow representation as the record-flow edges - a
    // global is effectively an input feeding the node, no different in kind
    // from a producer node's output record - just running from the global
    // box *to* the node that reads it (so it lines up above it) and dashed
    // (`-[dashed]->`) to still read as visually distinct from a record edge
    // at a glance. Unlabeled: the "Globals used:" list in the node box
    // already spells out identifier + slot + type, so the edge itself stays
    // plain to reduce clutter.
    if (GLOBAL_BOXES_ENABLED) {
        for (const n of nodes) {
            const group = groupDir(n);
            for (const name of n.globalsUsed || []) {
                lines.push(`${globalAlias(name, group)} -[dashed]-> ${n.id}`);
            }
        }
    }

    // A single legend - PlantUML only keeps one (a second legend/endlegend
    // block was found to silently replace the first rather than coexist
    // with it), so the color/launch-mode key, border/edge explanations, and
    // the global resource table all have to live in the same block.
    // A little literal padding space around every legend table cell (both
    // this one and the color/launch-mode one below), since PlantUML's
    // legend pipe-tables have no cell-padding skinparam of their own.
    const pad = (s) => `  ${s}  `;

    lines.push('');
    lines.push('legend right');

    // Global resource table - lists *every* discovered global regardless of
    // whether any node reads it, so this is now the only place an unused
    // global shows up at all (it no longer gets its own box/package). The
    // identifier column reuses theme.globalHighlight (bold, like the global
    // box's own name line) so a name reads the same wherever it appears.
    if (globalsIndex.size > 0) {
        const allGlobalsSorted = [...globalsIndex.values()].sort(
            (a, b) => a.regType.localeCompare(b.regType) || a.regSlot - b.regSlot
        );
        lines.push('  Global resources:');
        lines.push(`  |${pad('Identifier')}|${pad('Slot')}|${pad('Kind')}|${pad('Value type')}|${pad('Used?')}|`);
        for (const g of allGlobalsSorted) {
            const used = globalUsedByGroups.get(g.name)?.size ? '✓' : '✗';
            const kind = `${g.rw ? 'RW' : ''}${g.kind}`;
            const identCell = `<b><color:${theme.globalHighlight}>${pumlEscape(g.name)}</color></b>`;
            lines.push(
                `  |${pad(identCell)}|${pad(`${g.regType}${g.regSlot}`)}|${pad(pumlEscape(kind))}|` +
                    `${pad(pumlEscape(g.valueType || '-'))}|${pad(used)}|`
            );
        }
        lines.push('  ');
        lines.push('  Register slot prefixes:');
        lines.push('  t<NR> := SRV (shader resource view) - read-only buffer/texture');
        lines.push('  u<NR> := UAV (unordered access view) - read-write buffer/texture');
        lines.push('  b<NR> := CBV (constant buffer view) - small constant-buffer data');
        lines.push('  s<NR> := sampler state');
        lines.push('  ');
    }

    lines.push(`  |${pad('Color')}|${pad('Launch mode')}|`);
    lines.push(`  |${pad(`<${theme.broadcasting}>`)}|${pad('broadcasting')}|`);
    lines.push(`  |${pad(`<${theme.coalescing}>`)}|${pad('coalescing')}|`);
    lines.push(`  |${pad(`<${theme.thread}>`)}|${pad('thread')}|`);
    lines.push(`  |${pad(`<${theme.mesh}>`)}|${pad('mesh')}|`);
    lines.push(`  |${pad(`<${theme.external}>`)}|${pad('external / unresolved reference')}|`);
    if (GLOBAL_BOXES_ENABLED) {
        lines.push(`  |${pad(`<${theme.globalBg}>`)}|${pad('global resource (StructuredBuffer/ConstantBuffer/... via register())')}|`);
    }
    lines.push('  Red border = graph entry point (NodeIsProgramEntry)');
    lines.push('  Dashed border = grid can expand to >1 thread group per invocation');
    lines.push('  (NodeMaxDispatchGrid, or NodeDispatchGrid != (1,1,1)); solid border = always');
    lines.push('  exactly one group (NodeDispatchGrid(1,1,1), thread launch, or coalescing)');
    if (GLOBAL_BOXES_ENABLED) {
        lines.push('  A dashed edge from a global resource box into a node means that node reads it -');
        lines.push('  a global is effectively an input too, just dashed to stay visually distinct from');
        lines.push('  a produced-record edge; each global is replicated once per consuming node-group');
        lines.push('  to keep edges short (see the global resource table above for the full, ungrouped list)');
    }
    lines.push('endlegend');

    lines.push('@enduml');
    return lines.join('\n');
}

module.exports = { renderNodeBlock, renderPlantUml };
